"use client"

import * as React from "react"

import { DashboardPage } from "@/components/mockups/dashboard/dashboard-page"
import { AppShell } from "@/components/shell/app-shell"
import { MockupShell } from "@/components/shell/mockup-shell"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"

/**
 * PROD-600 — the dashboard brought in line with the design system, in the
 * product chrome. The period buttons switch the data the way the page does;
 * the reviewer switch up top empties the window, so the zero and -100% case
 * the ticket asks for can be checked on every period.
 */
export default function DashboardRoute() {
  const [data, setData] = React.useState<"calls" | "none">("calls")

  return (
    <MockupShell
      actions={
        <ToggleGroup
          onValueChange={(next) => {
            if (next) setData(next as "calls" | "none")
          }}
          size="sm"
          type="single"
          value={data}
          variant="outline"
        >
          <ToggleGroupItem value="calls">Calls</ToggleGroupItem>
          <ToggleGroupItem value="none">No calls</ToggleGroupItem>
        </ToggleGroup>
      }
      title="Dashboard in line with the design system"
    >
      <AppShell active="Dashboard">
        <div className="flex flex-1 flex-col p-3 lg:p-4">
          <DashboardPage noCalls={data === "none"} />
        </div>
      </AppShell>
    </MockupShell>
  )
}

"use client"

import * as React from "react"
import { Area, AreaChart, CartesianGrid, XAxis, YAxis } from "recharts"

import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  type ChartConfig,
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
} from "@/components/ui/chart"
import { cn } from "@/lib/utils"
import type { ChartPoint, Series } from "@/lib/mockups/dashboard-data"

/* Violet and blue, chart-6 and chart-2. The pair passes the palette checks
   (lightness band, colour-blind separation, contrast on the card); chart-1,
   the brand purple, is too dark to sit beside either as a line. */
const CHART_CONFIG = {
  inbound: { label: "Inbound", color: "var(--chart-6)" },
  outbound: { label: "Outbound", color: "var(--chart-2)" },
} satisfies ChartConfig

const SERIES_KEY: Record<Series, string> = {
  inbound: "bg-chart-6",
  outbound: "bg-chart-2",
}

/* An SVG id from React's, which may carry characters `url(#…)` will not take. */
function useSvgId(prefix: string) {
  return `${prefix}-${React.useId().replace(/[^a-zA-Z0-9-]/g, "")}`
}

/* Fades a series in at its first point and out at its last, so its line and
   wash start and stop softly instead of at a hard vertical edge. The mask
   sits on the series' own paths, so the axes beside them stay sharp. It is an
   alpha mask, which reads only each stop's opacity. */
function EdgeFade({ id }: { id: string }) {
  return (
    <>
      <linearGradient id={`${id}-ramp`} x1="0" x2="1" y1="0" y2="0">
        <stop offset="0%" stopColor="currentColor" stopOpacity={0} />
        <stop offset="8%" stopColor="currentColor" stopOpacity={1} />
        <stop offset="92%" stopColor="currentColor" stopOpacity={1} />
        <stop offset="100%" stopColor="currentColor" stopOpacity={0} />
      </linearGradient>
      <mask
        id={id}
        maskContentUnits="objectBoundingBox"
        style={{ maskType: "alpha" }}
      >
        {/* Taller than the path, so a 2px stroke at a peak is not shaved. */}
        <rect fill={`url(#${id}-ramp)`} height="1.2" width="1" y="-0.1" />
      </mask>
    </>
  )
}

/* A short stroke, drawn like the line it names. */
function SeriesKey({ series }: { series: Series }) {
  return (
    <span
      aria-hidden
      className={cn("h-0.5 w-3 shrink-0 rounded-full", SERIES_KEY[series])}
    />
  )
}

/**
 * One series across the period, small and without axes, so the Inbound and
 * Outbound cards carry the chart's colour as data rather than decoration.
 * The big chart below is where it is read; this only shows its shape. It has
 * no margin of its own: the card places it, flush to its bottom and end edges.
 */
export function Sparkline({
  className,
  points,
  series,
}: {
  className?: string
  points: ChartPoint[]
  series: Series
}) {
  return (
    <ChartContainer
      aria-hidden
      className={cn("aspect-auto", className)}
      config={{ [series]: CHART_CONFIG[series] }}
    >
      <AreaChart
        data={points}
        margin={{ bottom: 0, left: 0, right: 0, top: 4 }}
      >
        <YAxis domain={[0, "dataMax"]} hide />
        <Area
          dataKey={series}
          dot={false}
          fill={`var(--color-${series})`}
          fillOpacity={0.1}
          isAnimationActive={false}
          stroke={`var(--color-${series})`}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth={2}
          type="monotone"
        />
      </AreaChart>
    </ChartContainer>
  )
}

/**
 * Two 2px lines over a light wash, not stacked, so each series reads on its
 * own against the other. Both fade in and out at their ends. The legend sits
 * on the title's line; under the title, what one point counts ("Calls each
 * hour, today"), which neither the title nor the axis says.
 */
export function CallVolumeChart({
  description,
  points,
}: {
  description: string
  points: ChartPoint[]
}) {
  const edgeFadeId = useSvgId("calls-edge-fade")
  return (
    <Card>
      <CardHeader>
        <CardTitle>Inbound vs outbound calls</CardTitle>
        <CardDescription>{description}</CardDescription>
        <CardAction className="flex items-center gap-4">
          {(["inbound", "outbound"] as const).map((series) => (
            <span
              className="flex items-center gap-2 text-sm text-muted-foreground"
              key={series}
            >
              <SeriesKey series={series} />
              {CHART_CONFIG[series].label}
            </span>
          ))}
        </CardAction>
      </CardHeader>
      <CardContent>
        <ChartContainer
          className="aspect-auto h-72 w-full"
          config={CHART_CONFIG}
        >
          <AreaChart
            accessibilityLayer
            data={points}
            margin={{ left: 0, right: 24, top: 8 }}
          >
            <CartesianGrid vertical={false} />
            <XAxis
              axisLine={false}
              dataKey="label"
              minTickGap={32}
              tickLine={false}
              tickMargin={8}
            />
            <YAxis
              allowDecimals={false}
              axisLine={false}
              tickCount={4}
              tickLine={false}
              tickMargin={8}
              width={40}
            />
            <ChartTooltip
              content={<ChartTooltipContent indicator="dot" />}
              cursor={{ stroke: "var(--border)" }}
            />
            <defs>
              <EdgeFade id={edgeFadeId} />
            </defs>
            {(["outbound", "inbound"] as const).map((series) => (
              <Area
                activeDot={{
                  r: 4,
                  stroke: "var(--card)",
                  strokeWidth: 2,
                }}
                dataKey={series}
                dot={false}
                fill={`var(--color-${series})`}
                fillOpacity={0.1}
                key={series}
                mask={`url(#${edgeFadeId})`}
                stroke={`var(--color-${series})`}
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                type="monotone"
              />
            ))}
          </AreaChart>
        </ChartContainer>
      </CardContent>
    </Card>
  )
}

"use client"

import * as React from "react"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import {
  CallVolumeChart,
  Sparkline,
} from "@/components/mockups/dashboard/call-volume-chart"
import {
  ChangeDownIcon,
  ChangeUpIcon,
} from "@/components/mockups/dashboard/icons"
import { PeriodSelector } from "@/components/mockups/dashboard/period-selector"
import { cn } from "@/lib/utils"
import {
  dashboardData,
  type ChartPoint,
  type CustomRange,
  type NumberCard,
  type Period,
} from "@/lib/mockups/dashboard-data"

/**
 * PROD-600 — the dashboard on the system.
 *
 * Every card is a plain `Card`: a title, then the number at the top of the type
 * scale. Colour is kept only where it means something. A change follows its
 * number on the same baseline, as X's analytics does, with no pill behind it:
 * green when it is good news, red when it is bad, and grey for average
 * duration, which is neither. Inbound and outbound draw their own line from the
 * chart, in its colour. What a change is compared against is said once,
 * beside the period it belongs to.
 */
export function DashboardPage({ noCalls }: { noCalls: boolean }) {
  const [period, setPeriod] = React.useState<Period>("today")
  const [range, setRange] = React.useState<CustomRange>()
  const data = dashboardData(period, { noCalls, range })

  return (
    <div className="flex flex-col gap-6">
      {/* The comparison reads on from the selected period: "Last 30 days",
          then "vs previous 30 days". */}
      <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
        <PeriodSelector
          onPeriodChange={setPeriod}
          onRangeApply={(next) => {
            setRange(next)
            setPeriod("custom")
          }}
          period={period}
          range={range}
        />
        <p className="text-sm text-muted-foreground">{data.comparison}</p>
      </div>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {data.summary.map((card) => (
          <NumberTile card={card} key={card.label} />
        ))}
      </div>

      <section className="flex flex-col gap-4">
        <h2 className="text-lg font-semibold">Call analytics</h2>
        <div className="grid grid-cols-2 gap-4 sm:grid-cols-3">
          {data.analytics.map((card) => (
            <NumberTile card={card} key={card.label} points={data.chart} />
          ))}
        </div>
      </section>

      <CallVolumeChart
        description={data.chartDescription}
        points={data.chart}
      />
    </div>
  )
}

function NumberTile({
  card,
  points,
}: {
  card: NumberCard
  points?: ChartPoint[]
}) {
  return (
    <Card className="relative">
      <CardHeader>
        <CardTitle>{card.label}</CardTitle>
      </CardHeader>
      <CardContent className="flex items-baseline gap-2">
        <p className="text-2xl font-semibold tabular-nums">{card.value}</p>
        {card.change === undefined ? null : (
          <Change percent={card.change} riseIsGood={card.riseIsGood} />
        )}
      </CardContent>
      {/* Flush to the card's bottom and end edges, outside its padding; the
          card's rounded corner clips it. Its start fades out instead of
          stopping at a hard edge. */}
      {card.series && points ? (
        <Sparkline
          className="absolute end-0 bottom-0 h-14 w-1/2 mask-l-from-60%"
          points={points}
          series={card.series}
        />
      ) : null}
    </Card>
  )
}

function Change({
  percent,
  riseIsGood,
}: {
  percent: number
  riseIsGood: boolean | undefined
}) {
  const Arrow = percent > 0 ? ChangeUpIcon : percent < 0 ? ChangeDownIcon : null
  /* The arrow is the sign; this says it to a screen reader. */
  const direction = percent > 0 ? "Up " : percent < 0 ? "Down " : ""
  const tone =
    percent === 0 || riseIsGood === undefined
      ? "neutral"
      : percent > 0 === riseIsGood
        ? "good"
        : "bad"
  /* The tint foregrounds, not `success` and `destructive` themselves: those
     are fill colours and too light to read as 14px text on a card. */
  return (
    <span
      className={cn(
        "flex items-center gap-0.5 text-sm font-medium tabular-nums",
        tone === "good" && "text-success-tint-foreground",
        tone === "bad" && "text-destructive-tint-foreground",
        tone === "neutral" && "text-muted-foreground",
      )}
    >
      {Arrow ? <Arrow aria-hidden className="size-4" strokeWidth={2} /> : null}
      <span className="sr-only">{direction}</span>
      {Math.abs(percent)}%
    </span>
  )
}

"use client"

import {
  ArrowDown02Icon,
  ArrowUp02Icon,
  Calendar03Icon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/* A change's direction, straight up or down beside its percentage. */
export const ChangeUpIcon = icon(ArrowUp02Icon, "ChangeUpIcon")
export const ChangeDownIcon = icon(ArrowDown02Icon, "ChangeDownIcon")

/* The period selector's custom range button. */
export const CustomRangeIcon = icon(Calendar03Icon, "CustomRangeIcon")

"use client"

import * as React from "react"
import type { DateRange } from "react-day-picker"

import { Button } from "@/components/ui/button"
import { Calendar } from "@/components/ui/calendar"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { CustomRangeIcon } from "@/components/mockups/dashboard/icons"
import {
  PRESET_PERIODS,
  rangeLabel,
  type CustomRange,
  type Period,
} from "@/lib/mockups/dashboard-data"

/**
 * The platform's period selector as it ships (`period-selector.tsx`), outside
 * PROD-600's scope. Only its copy moves to sentence case, which the lint
 * requires of every string here.
 */
export function PeriodSelector({
  period,
  range,
  onPeriodChange,
  onRangeApply,
}: {
  period: Period
  range: CustomRange | undefined
  onPeriodChange: (period: Period) => void
  onRangeApply: (range: CustomRange) => void
}) {
  const [open, setOpen] = React.useState(false)
  const [draft, setDraft] = React.useState<DateRange | undefined>(range)

  return (
    <div className="flex items-center gap-2">
      {PRESET_PERIODS.map((preset) => (
        <Button
          key={preset.id}
          onClick={() => onPeriodChange(preset.id)}
          size="sm"
          variant={period === preset.id ? "default" : "outline"}
        >
          {preset.label}
        </Button>
      ))}

      <Popover
        onOpenChange={(next) => {
          setOpen(next)
          if (next) setDraft(range)
        }}
        open={open}
      >
        <PopoverTrigger asChild>
          <Button
            size="sm"
            variant={period === "custom" ? "default" : "outline"}
          >
            <CustomRangeIcon />
            {period === "custom" && range
              ? rangeLabel(range)
              : "Custom range (UTC)"}
          </Button>
        </PopoverTrigger>
        <PopoverContent align="end" className="w-auto">
          <Calendar
            disabled={{ after: new Date(Date.UTC(2026, 9, 20)) }}
            mode="range"
            numberOfMonths={2}
            onSelect={setDraft}
            selected={draft}
          />
          <div className="flex justify-between gap-2 border-t pt-3">
            <Button
              disabled={!draft?.from}
              onClick={() => setDraft(undefined)}
              size="sm"
              variant="outline"
            >
              Clear
            </Button>
            <Button
              disabled={!draft?.from || !draft.to}
              onClick={() => {
                if (!draft?.from || !draft.to) return
                onRangeApply({ from: draft.from, to: draft.to })
                setOpen(false)
              }}
              size="sm"
            >
              Apply range
            </Button>
          </div>
        </PopoverContent>
      </Popover>
    </div>
  )
}

